import { Component, inject, signal } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import {
  TablerIconComponent, IconLayoutDashboard, IconUsers, IconCalendarTime,
  IconReportAnalytics, IconSettings, IconBell, IconSearch, IconChevronRight,
  IconChevronDown, IconBuilding, IconFileText, IconUserPlus, IconBriefcase,
  IconLock, IconSitemap, IconCalendarStats,
  IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand,
} from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import { HrmAppShell, HrmTopNav, HrmSideNav, HrmNavItem, HrmNavSection, HrmSideNavUser, HrmDropdown } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · App Shell (Appshell) — mặc định: Side Nav đầy đủ (chuyển tài khoản + khối user)
 *  bên trái, page content bên phải (hướng mắt vào màn hình). Example: 3 bố cục. Song ngữ qua i18n docs.appShell.*. */
@Component({
  selector: 'sg-doc-app-shell',
  imports: [NgTemplateOutlet, TranslateModule, TablerIconComponent, NzDropDownModule, NzMenuModule, HrmDropdown, HrmAppShell, HrmTopNav, HrmSideNav, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Appshell" [title]="'docs.appShell.title' | translate" [desc]="'docs.appShell.desc' | translate">

      <div sgOverview>
        <div class="frame">
          <hrm-app-shell>
            <hrm-side-nav appSideNav [sections]="nav" [selectedKey]="sel()" (itemClick)="sel.set($event.key)"
              [collapsed]="colOv()" (collapsedChange)="colOv.set($event)"
              [caretIcon]="caret" [logoSrc]="logo" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand">
              <button snActions type="button" class="as-ico" [attr.aria-label]="'docs.appShell.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
              <button snHead type="button" class="sn-acct" [class.sn-acct--mini]="colOv()" [hrmDropdown]="acctMenu" hrmDropdownTrigger="click" [attr.aria-label]="'docs.appShell.switchAccount' | translate">
                <span class="sn-acct-ic"><tabler-icon [icon]="building" [size]="18" /></span>
                @if (!colOv()) {
                  <span style="flex:1;min-width:0">
                    <span style="display:block;font-size: var(--fs-14);font-weight:600;color:var(--text-strong)">{{ account().name }}</span>
                    <span style="display:block;font-size: var(--fs-12);color:var(--text-sub)">{{ account().sub }}</span>
                  </span>
                  <tabler-icon [icon]="chevDown" [size]="16" style="color:var(--text-soft)" />
                }
              </button>
              <button snFooter type="button" class="sn-user" [class.sn-user--mini]="colOv()" [hrmDropdown]="userMenu" hrmDropdownTrigger="click" [attr.aria-label]="'docs.appShell.switchAccount' | translate">
                <span class="sn-user-av">{{ me.initials }}</span>
                @if (!colOv()) {
                  <span class="sn-user-info">
                    <span class="sn-user-name">{{ me.name }}</span>
                    <span class="sn-user-mail">{{ me.email }}</span>
                  </span>
                  <tabler-icon [icon]="settings" [size]="16" class="sn-user-gear" />
                }
              </button>
            </hrm-side-nav>
            <ng-container *ngTemplateOutlet="page" />
          </hrm-app-shell>
        </div>
        <p style="font-size: var(--fs-13);color:var(--text-sub);margin:12px 0 0;max-width:60ch;line-height:1.5" [innerHTML]="'docs.appShell.ovNote' | translate"></p>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.appShell.purpose' | translate"
          [when]="when"
          [behavior]="'docs.appShell.behavior' | translate"
          [avoid]="'docs.appShell.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do><span [innerHTML]="'docs.appShell.do1' | translate"></span></sg-do>
        <sg-do><span [innerHTML]="'docs.appShell.do2' | translate"></span></sg-do>
        <sg-dont>{{ 'docs.appShell.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.appShell.exSideT' | translate"
          [desc]="'docs.appShell.exSideD' | translate">
          <sg-row>
            <div class="frame" style="width:100%">
              <hrm-app-shell>
                <hrm-side-nav appSideNav [sections]="nav" [selectedKey]="selA()" (itemClick)="selA.set($event.key)"
                  [caretIcon]="caret" [logoSrc]="logo" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand">
                  <button snActions type="button" class="as-ico" [attr.aria-label]="'docs.appShell.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
                  <button snFooter type="button" class="sn-user" [hrmDropdown]="userMenu" hrmDropdownTrigger="click" [attr.aria-label]="'docs.appShell.switchAccount' | translate">
                    <span class="sn-user-av">{{ me.initials }}</span>
                    <span class="sn-user-info">
                      <span class="sn-user-name">{{ me.name }}</span>
                      <span class="sn-user-mail">{{ me.email }}</span>
                    </span>
                    <tabler-icon [icon]="settings" [size]="16" class="sn-user-gear" />
                  </button>
                </hrm-side-nav>
                <ng-container *ngTemplateOutlet="page" />
              </hrm-app-shell>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.appShell.exTopT' | translate"
          [desc]="'docs.appShell.exTopD' | translate">
          <sg-row>
            <div class="frame" style="width:100%">
              <hrm-app-shell>
                <hrm-top-nav appTopNav [items]="topItems" [selectedKey]="selB()" (itemClick)="selB.set($event.key)" [logoSrc]="logo">
                  <button tnActions type="button" class="as-ico" [attr.aria-label]="'docs.appShell.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
                  <span tnActions class="as-av">ĐV</span>
                </hrm-top-nav>
                <ng-container *ngTemplateOutlet="page" />
              </hrm-app-shell>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.appShell.exBothT' | translate"
          [desc]="'docs.appShell.exBothD' | translate">
          <sg-row>
            <div class="frame" style="width:100%">
              <hrm-app-shell>
                <hrm-side-nav appSideNav [sections]="nav" [selectedKey]="selC()" (itemClick)="selC.set($event.key)"
                  [caretIcon]="caret" [logoSrc]="logo" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand">
                  <button snActions type="button" class="as-ico" [attr.aria-label]="'docs.appShell.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
                  <button snFooter type="button" class="sn-user" [hrmDropdown]="userMenu" hrmDropdownTrigger="click" [attr.aria-label]="'docs.appShell.switchAccount' | translate">
                    <span class="sn-user-av">{{ me.initials }}</span>
                    <span class="sn-user-info">
                      <span class="sn-user-name">{{ me.name }}</span>
                      <span class="sn-user-mail">{{ me.email }}</span>
                    </span>
                    <tabler-icon [icon]="settings" [size]="16" class="sn-user-gear" />
                  </button>
                </hrm-side-nav>
                <hrm-top-nav appTopNav [items]="topItems" selectedKey="all">
                  <span tnActions class="as-search" [class.is-open]="asOpen()" (click)="asOpen.set(!asOpen())"><tabler-icon [icon]="search" [size]="16" /><input [placeholder]="'docs.appShell.searchPh' | translate" (click)="$event.stopPropagation()" /></span>
                  <button tnActions type="button" class="as-ico" [attr.aria-label]="'docs.appShell.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
                  <span tnActions class="as-av">ĐV</span>
                </hrm-top-nav>
                <ng-container *ngTemplateOutlet="page" />
              </hrm-app-shell>
            </div>
          </sg-row>
        </sg-example>
      </div>
    </sg-doc>

    <!-- Vùng nội dung: KHUNG MẶC ĐỊNH — chỗ trống giữa trang để đặt feature.
         AI/đồng đội thay placeholder này bằng UI tính năng (list-page, form, dashboard…). -->
    <ng-template #page>
      <div class="pg-empty">
        <div class="pg-empty-title">{{ 'docs.appShell.contentTitle' | translate }}</div>
        <div class="pg-empty-sub">{{ 'docs.appShell.contentSub' | translate }}</div>
      </div>
    </ng-template>

    <!-- Dropdown chuyển tài khoản (tổ chức) -->
    <nz-dropdown-menu #acctMenu="nzDropdownMenu">
      <ul nz-menu style="min-width:230px">
        <li nz-menu-item (click)="setAcct('Tập đoàn VNR', tr('acctEnterprise'))">Tập đoàn VNR</li>
        <li nz-menu-item (click)="setAcct('VNR Software', tr('acctHcm'))">VNR Software</li>
        <li nz-menu-item (click)="setAcct('VNR Academy', tr('acctHanoi'))">VNR Academy</li>
      </ul>
    </nz-dropdown-menu>

    <!-- Menu tài khoản (khối user footer) — đồng bộ với Side Nav doc. -->
    <nz-dropdown-menu #userMenu="nzDropdownMenu">
      <ul nz-menu style="min-width:200px">
        <li nz-menu-item>{{ 'docs.sideNav.userProfile' | translate }}</li>
        <li nz-menu-item>{{ 'docs.sideNav.userSettings' | translate }}</li>
        <li nz-menu-divider></li>
        <li nz-menu-item style="color:var(--error-base)">{{ 'docs.sideNav.userLogout' | translate }}</li>
      </ul>
    </nz-dropdown-menu>
  `,
  styles: [`
    .frame { height: 460px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); overflow: hidden; }
    .as-ico { display: grid; place-items: center; width: 34px; height: 34px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .as-ico:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    .as-av { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--primary-base); color: #fff; font-size: var(--fs-13); font-weight: 600; }
    .as-search { display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface-subtle); color: var(--text-sub); }
    .as-search input { border: 0; background: transparent; outline: none; font: inherit; font-size: var(--fs-13); color: var(--text-body); width: 140px; }
    /* Responsive: chỉ khi RẤT hẹp (.tn--narrow, lib bật ở <560px) → search thu thành ICON.
       Độc lập ngưỡng hamburger (820) → search vẫn full ở khoảng 560–820. ::ng-deep vì
       .tn--narrow là element của LIB. */
    ::ng-deep .tn--narrow .as-search { flex: none; box-sizing: border-box; width: 34px; height: 34px; padding: 0; justify-content: center; cursor: pointer; background: transparent; border: 0; color: var(--text-sub); }
    ::ng-deep .tn--narrow .as-search:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    /* Bấm icon → mở lại ô nhập đầy đủ (dù đang hẹp). */
    ::ng-deep .tn--narrow .as-search.is-open { width: auto; height: auto; padding: 6px 10px; justify-content: flex-start; background: var(--bg-surface-subtle); border: 1px solid var(--border-sub); }
    ::ng-deep .tn--narrow .as-search.is-open input { display: inline; }
    ::ng-deep .tn--narrow .as-search input { display: none; }

    /* Nút chuyển tài khoản (snHead) — giống mẫu Side Nav. */
    .sn-acct { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); cursor: pointer; text-align: left; transition: border-color var(--duration-fast, .15s) var(--ease-out, ease); }
    .sn-acct:hover { border-color: var(--primary-base); }
    .sn-acct--mini { width: auto; padding: 4px; border-color: transparent; background: transparent; }
    .sn-acct-ic { display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); flex: none; }
    /* Khối user footer (snFooter) — đồng bộ Side Nav doc: avatar + tên + email + bánh răng, mở userMenu. */
    .sn-user { display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px 8px; border: 0; background: transparent; border-radius: var(--radius-lg); cursor: pointer; text-align: left; transition: background var(--duration-fast, .15s) var(--ease-out, ease); }
    .sn-user:hover { background: var(--bg-surface-subtle); }
    .sn-user--mini { width: auto; padding: 4px; }
    .sn-user-av { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--primary-base); color: #fff; font-size: var(--fs-13); font-weight: 600; flex: none; }
    .sn-user-info { flex: 1; min-width: 0; }
    .sn-user-name { display: block; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sn-user-mail { display: block; font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sn-user-gear { color: var(--text-soft); flex: none; }

    /* Vùng content: KHUNG MẶC ĐỊNH — placeholder giữa trang (đồng đội/AI thay bằng feature). */
    .pg-empty { height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; text-align: center; padding: 24px; background: var(--bg-canvas); }
    .pg-empty-title { font-size: var(--fs-20); font-weight: 700; color: var(--text-strong); }
    .pg-empty-sub { font-size: var(--fs-13); color: var(--text-sub); max-width: 42ch; line-height: 1.5; }
  `],
})
export class SgDocAppShell {
  private readonly t = inject(TranslateService);
  protected tr(key: string): string { return this.t.instant('docs.appShell.' + key); }

  protected readonly caret = IconChevronRight;
  protected readonly chev = IconChevronRight;
  protected readonly chevDown = IconChevronDown;
  protected readonly building = IconBuilding;
  protected readonly bell = IconBell;
  protected readonly search = IconSearch;
  protected readonly settings = IconSettings;
  protected readonly sbCollapse = IconLayoutSidebarLeftCollapse;
  protected readonly sbExpand = IconLayoutSidebarLeftExpand;
  protected readonly logo = '/assets/vnr-logo-full.svg';
  protected readonly logoMark = '/assets/vnr-logo-mark.svg';

  protected readonly me: HrmSideNavUser = { name: 'Đặng Vũ', email: 'danganh@vnr.vn', initials: 'ĐV' };
  protected onSwitch(): void { /* demo: chỗ mở dialog chuyển tài khoản */ }

  protected readonly colOv = signal(false);
  protected readonly account = signal({ name: 'Tập đoàn VNR', sub: this.tr('acctEnterprise') });
  protected setAcct(name: string, sub: string): void { this.account.set({ name, sub }); }

  protected readonly sel = signal('dash');
  protected readonly selA = signal('dash');
  protected readonly selB = signal('all');
  protected readonly selC = signal('dash');
  /** Ô tìm kiếm (khi thu icon lúc hẹp) đang mở lại để nhập. */
  protected readonly asOpen = signal(false);

  protected get nav(): HrmNavSection[] {
    return [
      { header: this.tr('navMain'), items: [
        { key: 'dash', label: this.tr('navDashboard'), icon: IconLayoutDashboard },
        { key: 'hr', label: this.tr('navHr'), icon: IconUsers, children: [
          { key: 'emp', label: this.tr('navEmpList'), icon: IconUsers },
          { key: 'org', label: this.tr('navOrg'), icon: IconSitemap },
          { key: 'contract', label: this.tr('navContract'), icon: IconFileText },
        ] },
        { key: 'att', label: this.tr('navAttendance'), icon: IconCalendarTime, children: [
          { key: 'timesheet', label: this.tr('navTimesheet'), icon: IconCalendarStats },
          { key: 'leave', label: this.tr('navLeave'), icon: IconCalendarTime },
        ] },
        { key: 'recruit', label: this.tr('navRecruit'), icon: IconUserPlus, children: [
          { key: 'jobs', label: this.tr('navJobs'), icon: IconBriefcase },
          { key: 'candidates', label: this.tr('navCandidates'), icon: IconUsers },
        ] },
      ] },
      { header: this.tr('navSystem'), items: [
        { key: 'rep', label: this.tr('navReport'), icon: IconReportAnalytics },
        { key: 'set', label: this.tr('navSettings'), icon: IconSettings, children: [
          { key: 'set-general', label: this.tr('navSettingsGeneral'), icon: IconSettings },
          { key: 'set-perm', label: this.tr('navSettingsPerm'), icon: IconLock },
        ] },
      ] },
    ];
  }

  protected get topItems(): HrmNavItem[] {
    return [
      { key: 'all', label: this.tr('navDashboard') },
      { key: 'hr', label: this.tr('navStaff') },
      { key: 'att', label: this.tr('navAttendance') },
      { key: 'pay', label: this.tr('navPayroll') },
    ];
  }

  protected readonly when = [
    'docs.appShell.when1',
    'docs.appShell.when2',
    'docs.appShell.when3',
  ];
}
